"use client"

import animation from "react-useanimations/lib/calendar"

import { UseAnimation, type UseAnimationProps } from "@/components/use-animation"

// "Calendar" from https://useanimations.com (MIT): https://useanimations.com/icons/calendar
export function AnimatedCalendar(
  props: Omit<UseAnimationProps, "animationData">
) {
  return (
    <UseAnimation
      animationData={animation.animationData}
      interaction="hover"
      {...props}
    />
  )
}
